async function getTile(t){const response=await fetch('./data/'+t.id+'.json');if(!response.ok)throw new Error('Saved map section unavailable');const data=await response.json();if(!Array.isArray(data.elements)||data.remark)throw new Error('Invalid map section');return data;}
