let perfStart=performance.now(),perfFrames=0,perfMs=[];
let lastFrame=performance.now();
function animate(now){requestAnimationFrame(animate);const elapsed=(now-lastFrame)/1000;const dt=Math.min(elapsed,.04);lastFrame=now;perfFrames++;perfMs.push(elapsed*1000);if(now-perfStart>2000){perfMs.sort((a,b)=>a-b);$('#perf').textContent=Math.round(perfFrames*1000/(now-perfStart))+' FPS · p95 '+Math.round(perfMs[Math.floor(perfMs.length*.95)]||0)+' ms · '+renderer.info.render.calls+' draws · '+renderer.info.render.triangles.toLocaleString()+' triangles';const drivePerf=$('#drive-perf');if(drivePerf)drivePerf.textContent=$('#perf').textContent;perfFrames=0;perfMs=[];perfStart=now;}atmosphere?.update(now,camera.position);if(driving.active){driving.update(Math.min(elapsed,.2));renderer.render(scene,camera);return;}if(flight){const t=Math.min((now-flight.start)/1100,1),s=t*t*(3-2*t);camera.position.lerpVectors(flight.from,flight.to,s);controls.target.lerpVectors(flight.fromTarget,flight.target,s);if(t===1)flight=null;}if(!flight)controls.target.y=heightAt(controls.target.x,controls.target.z);camera.position.y=Math.max(camera.position.y,heightAt(camera.position.x,camera.position.z)+3);controls.update();renderer.render(scene,camera);}requestAnimationFrame(animate);
try{await loadRoadModel();terrainInfo=await loadTerrain(scene);for(const [i,needle] of ['Ismail','Mihai Viteazul','Renașterii','Miorița'].entries()){const match=Object.values(terrainInfo.profiles).find(p=>p.bridge&&p.name.includes(needle)&&!['footway','path','steps'].includes(p.highway));if(match){const pt=match.points[Math.floor(match.points.length/2)];places['bridge'+i]=[ORIGIN.lat-pt[1]/111320,ORIGIN.lon+pt[0]/(111320*Math.cos(ORIGIN.lat*Math.PI/180))];const o=document.createElement('option');o.value='bridge'+i;o.textContent='Bridge · '+match.name;$('#place').append(o);}}ground.position.y=terrainInfo.meta.minElevation-terrainInfo.meta.offset-20;grid.visible=false;realismData=await(await fetch('./data/realism.json')).json();setupDestinations();manifest=await(await fetch('./data/manifest.json')).json();status('Drawing the city centre','Real building footprints from OpenStreetMap');const center=await fetch('./data/center.json');if(center.ok)await ingest(await center.json());await loadTiles(nearTiles(...active));try{const details=await addStreetDetails(scene,driving,realismData.extra);atmosphere=addAtmosphere(scene,realismData);$('#landscape').onchange=e=>atmosphere.vegetation.visible=e.target.checked;applyTime();$('#street-details').onchange=e=>details.group.visible=e.target.checked;$('#street-count').textContent=details.trees.toLocaleString()+' trees · '+details.benches.toLocaleString()+' benches';}catch(e){$('#street-count').textContent='Street details could not load; reload to retry.';console.error(e);}}catch(e){status('The city data could not load','Check your connection and reload the page.','error');console.error(e);}

function setupDestinations(){const select=$('#destination');realismData.pois.sort((a,b)=>a.name.localeCompare(b.name,'ro'));for(const [i,p] of realismData.pois.entries()){const o=document.createElement('option');o.value=i;o.textContent=p.name;select.append(o);}select.onchange=()=>{if(select.value===''){driving.setDestination(null);return;}const p=realismData.pois[+select.value],xz=project(p);driving.setDestination({name:p.name,x:xz[0],z:xz[1]});if(!driving.active){active=[p.lat,p.lon];fly(p.lat,p.lon,500);if(!busy)loadTiles(nearTiles(...active));}};}

function applyTime(){const hour=+$('#time-of-day').value,daylight=Math.max(0,Math.sin((hour-6)/12*Math.PI)),twilight=(hour>=5&&hour<7)||(hour>=17&&hour<20),night=daylight<.15;$('#clock-label').textContent=String(Math.floor(hour)%24).padStart(2,'0')+':'+String(Math.round((hour%1)*60)).padStart(2,'0');ambient.intensity=.16+daylight*1.94;sun.intensity=daylight*3.4;sun.position.set(Math.cos((hour-6)/12*Math.PI)*3000,Math.max(50,daylight*3000),1800);scene.background.set(night?(twilight?'#26354b':'#070d1e'):'#172b36');scene.fog.color.copy(scene.background);atmosphere?.setDusk(night);driving.setDusk(night);$('#night-skip').textContent=night?'Skip to day':'Skip to night';}
$('#time-of-day').oninput=applyTime;$('#night-skip').onclick=()=>{$('#time-of-day').value=$('#night-skip').textContent==='Skip to day'?12:22;applyTime();};$('#day-skip').onclick=()=>{$('#time-of-day').value=12;applyTime();};$('#dusk-skip').onclick=()=>{$('#time-of-day').value=18.5;applyTime();};
